// AQUI defines que es una incidencia. Ajusta estas reglas a tu servicio.
// $json es la respuesta de tu API de estado.
const datos = $json || {};
const problemas = [];

// Regla 1: el campo estado debe valer 'ok'.
if (datos.estado && datos.estado !== 'ok') {
  problemas.push('El servicio responde estado "' + datos.estado + '"');
}

// Regla 2: demasiados casos pendientes (cambia el umbral 20 por el tuyo).
const pendientes = Number(datos.pendientes || 0);
if (pendientes > 20) {
  problemas.push('Hay ' + pendientes + ' casos pendientes (umbral: 20)');
}

// Regla 3 (ejemplo, borra o adapta): respuesta vacia = sospechoso.
if (Object.keys(datos).length === 0) {
  problemas.push('La API de estado respondio vacia');
}

return [ { json: {
  alerta: problemas.length > 0,
  motivo: problemas.join(' · ') || 'sin incidencias',
  revisado: new Date().toISOString()
} } ];

